WITH valid_departments AS (SELECT *, ROUND(budget * 1.07, 2) AS budget_adjusted FROM departments WHERE dept_name IN ('Sales', 'Legal') AND budget <= 1403000 AND location = 'London'), summary AS (SELECT CASE WHEN budget >= 4465000 THEN 'high' WHEN budget >= 1924000 THEN 'mid' ELSE 'low' END AS budget_bucket, MAX(budget) AS max_budget FROM valid_departments GROUP BY CASE WHEN budget >= 4465000 THEN 'high' WHEN budget >= 1924000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, max_budget FROM summary WHERE max_budget >= 2018000;
